/* ---------- language swipe ---------- */
:root[data-skin="report"][data-locale-swipe]::view-transition { pointer-events: none; }
:root[data-skin="report"][data-locale-swipe]::view-transition-group(root) { animation: none; }
:root[data-skin="report"][data-locale-swipe]::view-transition-image-pair(root) { isolation: isolate; }
:root[data-skin="report"][data-locale-swipe]::view-transition-old(root),
:root[data-skin="report"][data-locale-swipe]::view-transition-new(root) { animation: none; mix-blend-mode: normal; }
/* The outgoing language is pushed right and wiped from the left. */
:root[data-skin="report"][data-locale-swipe]::view-transition-old(root) {
  z-index: 2; animation: rx-locale-out 680ms cubic-bezier(.65, 0, .35, 1) both;
}
/* The incoming language slides in a little behind the edge. */
:root[data-skin="report"][data-locale-swipe]::view-transition-new(root) {
  z-index: 1; animation: rx-locale-in 680ms cubic-bezier(.16, 1, .3, 1) both;
}
:root[data-skin="report"][data-locale-swipe] *,
:root[data-skin="report"][data-locale-swipe] *::before,
:root[data-skin="report"][data-locale-swipe] *::after { transition: none !important; }
@keyframes rx-locale-out {
  from { clip-path: inset(0 0 0 0); transform: none; }
  to { clip-path: inset(0 0 0 100%); transform: translateX(48px); }
}
@keyframes rx-locale-in {
  from { transform: translateX(-36px); opacity: .25; }
  60% { opacity: 1; }
  to { transform: none; opacity: 1; }
}
